package com.priperi;

import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.journeyapps.barcodescanner.*;import org.json.JSONObject;import java.util.Collections;
import com.google.zxing.qrcode.QRCodeWriter;

/** One private QR/NFC page; camera exists only inside a guarded, dismissible popup. */
public final class ContactCodeActivity extends PrivateActivity {
 private NfcContactPanel nfc;private String ownCode,ownName,owner,lastAttempt;private long lastAttemptAt;private ImageView codeImage;private TextView username,status;
 private BarcodeView camera;private boolean privateReady,scanning,busy,cameraStarted,permissionPending;
 private androidx.appcompat.app.AlertDialog cameraDialog,confirmation;private int generation,identityGeneration;private final Handler cameraHandler=new Handler(Looper.getMainLooper());
 private boolean alive(){return privateReady&&!environmentBlocked&&!isFinishing()&&!isDestroyed()&&owner!=null&&owner.equals(Session.uid());}
 @Override protected void onCreate(Bundle saved){super.onCreate(saved);root=Ui.page(this);root.setVisibility(View.INVISIBLE);LinearLayout header=Ui.row(this);header.addView(Ui.iconButton(this,"back","Back",v->finish()));header.addView(Ui.title(this,"Add a contact",23));root.addView(header);
  LinearLayout show=Ui.scroll(this,root);show.setGravity(Gravity.CENTER_HORIZONTAL);Ui.space(this,show,8);username=Ui.title(this,"Your code",23);username.setGravity(Gravity.CENTER);show.addView(username);Ui.space(this,show,14);nfc=new NfcContactPanel(this,show);Ui.space(this,show,16);
  LinearLayout paper=Ui.column(this);Ui.pad(this,paper,12);paper.setBackground(Ui.shape(this,getColor(R.color.qr_paper),26));codeImage=new ImageView(this);codeImage.setContentDescription("Your Priperi contact QR code");codeImage.setScaleType(ImageView.ScaleType.FIT_CENTER);codeImage.setAdjustViewBounds(true);paper.addView(codeImage,new LinearLayout.LayoutParams(-1,Ui.dp(this,Math.min(260,Math.max(160,Math.min(getResources().getConfiguration().screenWidthDp-90,getResources().getConfiguration().screenHeightDp-390))))));show.addView(paper,new LinearLayout.LayoutParams(-1,-2));Ui.space(this,show,18);
  show.addView(Ui.button(this,"Scan a code",true,v->chooseScan()));
 }
 @Override protected void ready(){owner=Session.uid();privateReady=true;String user=owner;int request=++identityGeneration;Repository.work(this,v->new String[]{v.account().getString("username"),ContactCode.encode(v.account().getString("uid"),v.identity().getString("fingerprint"))},data->{if(!alive()||request!=identityGeneration||!user.equals(Session.uid()))return;ownName=data[0];ownCode=data[1];username.setText("@"+ownName);try{codeImage.setImageBitmap(bitmap(ownCode,getColor(R.color.qr_ink),getColor(R.color.qr_paper)));}catch(Exception e){username.setText("Reopen this page to show your code.");}if(permissionPending&&ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){permissionPending=false;openScanner();}else if(!scanning)nfc.open(owner,ownName,ownCode);},error->{if(alive())username.setText(error);});}
 static Bitmap bitmap(String value)throws WriterException{return bitmap(value,Color.rgb(18,46,51),Color.rgb(226,241,237));}
 static DecoderFactory scannerDecoder(){return new DefaultDecoderFactory(Collections.singletonList(BarcodeFormat.QR_CODE),null,null,2);}
 static Bitmap bitmap(String value,int ink,int paper)throws WriterException{BitMatrix bits=new QRCodeWriter().encode(value,BarcodeFormat.QR_CODE,640,640);int[] pixels=new int[640*640];for(int y=0;y<640;y++)for(int x=0;x<640;x++)pixels[y*640+x]=bits.get(x,y)?ink:paper;return Bitmap.createBitmap(pixels,640,640,Bitmap.Config.ARGB_8888);}
 private void chooseScan(){if(!alive()||busy||scanning)return;if(!getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_ANY)){android.widget.Toast.makeText(this,"No camera available. Search a username instead.",android.widget.Toast.LENGTH_SHORT).show();return;}nfc.hide();if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){permissionPending=true;ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},84);return;}openScanner();}
 private void openScanner(){if(!alive()||scanning)return;nfc.hide();scanning=true;LinearLayout box=Ui.column(this);Ui.pad(this,box,16);camera=new BarcodeView(this);camera.setDecoderFactory(scannerDecoder());camera.setContentDescription("Contact code camera preview");box.addView(camera,new LinearLayout.LayoutParams(-1,Ui.dp(this,Math.max(96,Math.min(240,getResources().getConfiguration().screenHeightDp/3)))));status=Ui.status(this,box);status.setText("Point at a Priperi code");camera.addStateListener(new CameraPreview.StateListener(){public void previewSized(){}public void previewStarted(){}public void previewStopped(){}public void cameraClosed(){}public void cameraError(Exception e){stopCamera();message("Camera unavailable. Close this window and try again.");}});
  cameraDialog=Ui.dialog(this).setTitle("Scan a code").setView(box).setNegativeButton("Close",null).create();cameraDialog.setOnDismissListener(d->{generation++;busy=false;scanning=false;lastAttempt=null;lastAttemptAt=0;cameraHandler.removeCallbacksAndMessages(null);stopCamera();camera=null;cameraDialog=null;if(alive()&&ownCode!=null)nfc.open(owner,ownName,ownCode);});cameraDialog.show();Ui.fadeIn(this,box);startCamera();}
 private void startCamera(){if(!alive()||!scanning||busy||cameraStarted||camera==null)return;try{cameraStarted=true;camera.resume();camera.decodeSingle(result->scanned(result.getText()));}catch(RuntimeException e){stopCamera();message("Camera unavailable. Close this window and try again.");}}
 private void stopCamera(){cameraStarted=false;if(camera!=null)camera.pause();}
 boolean contactScreenReady(){return alive()&&!scanning&&root.isShown();}
 private void message(String value){if(status!=null)status.setText(value);}
 private void retryCamera(){int request=generation;cameraHandler.postDelayed(()->{if(alive()&&scanning&&!busy&&(confirmation==null||!confirmation.isShowing())&&request==generation)startCamera();},900);}
 void scanned(String value){if(!alive()||!scanning||busy||(confirmation!=null&&confirmation.isShowing()))return;stopCamera();ContactCode parsed;try{parsed=ContactCode.parse(value);if(parsed.uid.equals(owner))throw new IllegalArgumentException("This is your own code. Scan your contact’s code instead.");}catch(IllegalArgumentException e){message(e.getMessage());retryCamera();return;}
  long now=SystemClock.elapsedRealtime();if(value.equals(lastAttempt)&&now-lastAttemptAt<15_000){retryCamera();return;}lastAttempt=value;lastAttemptAt=now;int request=++generation;String user=owner;busy=true;message("Checking contact…");Repository.work(this,v->Repository.resolveCode(v,parsed),peer->{if(!alive()||request!=generation||!user.equals(Session.uid()))return;busy=false;message("Contact found");confirmation=Ui.dialog(this).setTitle("Chat with @"+peer.optString("username")+"?").setMessage("Only confirm if this code came directly from the person you want to contact.").setNegativeButton("Cancel",(d,w)->{if(cameraDialog!=null)cameraDialog.dismiss();}).setPositiveButton("Verify and open",(d,w)->{if(!alive()||request!=generation||busy)return;busy=true;Repository.work(this,v->{if(!user.equals(Session.uid()))throw new SecurityException("Sign in again.");JSONObject current=Repository.resolveCode(v,parsed);v.pin(current);v.contactFlag(parsed.uid,"verified",true);return true;},ok->{if(alive()&&request==generation){startActivity(new Intent(this,ChatActivity.class).putExtra("peer",parsed.uid));finish();}},error->{if(alive()&&request==generation){busy=false;message(error);retryCamera();}});}).show();confirmation.setOnCancelListener(d->{if(cameraDialog!=null)cameraDialog.dismiss();});},error->{if(alive()&&request==generation){busy=false;message(error);retryCamera();}});
 }
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==84){permissionPending=results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED;if(permissionPending&&alive()){permissionPending=false;openScanner();}else if(!permissionPending&&alive()&&ownCode!=null)nfc.open(owner,ownName,ownCode);}}
 private void conceal(){privateReady=false;if(nfc!=null)nfc.hide();ownCode=null;ownName=null;generation++;identityGeneration++;busy=false;cameraHandler.removeCallbacksAndMessages(null);if(confirmation!=null){confirmation.dismiss();confirmation=null;}if(cameraDialog!=null)cameraDialog.dismiss();stopCamera();}
 @Override protected void onPause(){conceal();super.onPause();}
 @Override protected void onEnvironmentBlocked(){conceal();}
 @Override protected void onDestroy(){cameraHandler.removeCallbacksAndMessages(null);super.onDestroy();}
}
